document.querySelectorAll('.legal-link').forEach(el => {
  el.addEventListener('click', () => {
    const page = el.dataset.legal;
    document.getElementById('legalTitle').textContent = page === 'terms' ? 'Terms & Conditions' : 'Privacy Policy';
    document.getElementById('legalContent').innerHTML = LEGAL_TEXT[page];
    document.getElementById('legalModal').classList.add('active');
  });
});
document.getElementById('legalCloseBtn').addEventListener('click', () => {
  document.getElementById('legalModal').classList.remove('active');
});
document.getElementById('legalModal').addEventListener('click', e => {
  if (e.target === e.currentTarget) document.getElementById('legalModal').classList.remove('active');
});

// Prevent arrow keys / space from scrolling the page (required: game must not scroll the iframe)
window.addEventListener('keydown', (e) => {
  if (['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Spacebar'].includes(e.key)) {
    e.preventDefault();
  }
}, { passive: false });

// Prevent the mobile long-press context menu / text-selection callout from appearing over the board
document.addEventListener('contextmenu', (e) => e.preventDefault());

// Pause/resume gameplay on visibility change
document.addEventListener('visibilitychange', () => {
  if (STATE.gameStarted && !STATE.gameComplete && !STATE.gameOver) {
    if (document.hidden) {
      crazySdk.game.gameplayStop();
      pauseGameTimer();
    } else {
      crazySdk.game.gameplayStart();
      resumeGameTimer();
    }
  }
});

/* ============================================================
   SCROLLBAR — custom thin overlay, visible only while scrolling
   ============================================================ */
(function(){
  var track = document.getElementById('scrollbar-track');
  var thumb = document.getElementById('scrollbar-thumb');
  if (!track || !thumb) return;
  var hideTimer, hasScrolled;
  function update(force){
    var ch = document.documentElement.scrollHeight;
    var vh = window.innerHeight;
    var st = window.scrollY || window.pageYOffset || document.documentElement.scrollTop || 0;
    if (st > 0) hasScrolled = true;
    if (!hasScrolled) return;
    var ratio = vh / ch;
    if (ratio >= 1) { track.classList.remove('show'); return; }
    var thumbH = Math.max(20, vh * ratio);
    var maxScroll = ch - vh;
    var thumbTop = (st / maxScroll) * (vh - thumbH);
    thumb.style.height = thumbH + 'px';
    thumb.style.top = Math.max(0, thumbTop) + 'px';
    track.classList.add('show');
    clearTimeout(hideTimer);
    hideTimer = setTimeout(function(){ track.classList.remove('show'); }, 600);
  }
  window.addEventListener('scroll', update, { passive: true });
  window.addEventListener('resize', function(){ update(true); }, { passive: true });
  update(true);
})();

/* ============================================================
   TUTORIAL — first-visit overlay
   ============================================================ */
const TUTORIAL_KEY = 'arcanum_tutorial_shown';

function dismissTutorial() {
  document.getElementById('tutorialModal').classList.remove('active');
  try { crazySdk.data.setItem(TUTORIAL_KEY, '1'); } catch(e) { localStorage.setItem(TUTORIAL_KEY, '1'); }
}

document.getElementById('tutorialBeginBtn').addEventListener('click', dismissTutorial);

document.getElementById('helpBtn').addEventListener('click', () => {
  try { crazySdk.data.removeItem(TUTORIAL_KEY); } catch(e) { localStorage.removeItem(TUTORIAL_KEY); }
  document.getElementById('tutorialModal').classList.add('active');
});
document.getElementById('tutorialModal').addEventListener('click', e => {
  if (e.target === e.currentTarget) dismissTutorial();
});

let tutorialAutoShown = false;
function showTutorialIfNeeded() {
  if (tutorialAutoShown) return;
  try {
    const shown = crazySdk.data.getItem(TUTORIAL_KEY);
    if (shown === '1') return;
  } catch(e) {
    if (localStorage.getItem(TUTORIAL_KEY) === '1') return;
  }
  // Don't pop the tutorial up over the splash screen — wait for it to be dismissed.
  const splash = document.getElementById('splashScreen');
  if (splash && !splashDismissed) return;
  tutorialAutoShown = true;
  setTimeout(() => {
    document.getElementById('tutorialModal').classList.add('active');
  }, 600);
}

/* ============================================================
   SPLASH SCREEN — animated intro, tap-to-skip or auto-dismiss
   ============================================================ */
const SPLASH_AUTO_DISMISS_MS = 2800;
let splashDismissed = false;

function dismissSplash() {
  if (splashDismissed) return;
  splashDismissed = true;
  const splash = document.getElementById('splashScreen');
  if (!splash) { showTutorialIfNeeded(); return; }
  splash.classList.add('splash-hidden');
  splash.removeEventListener('click', dismissSplash);
  window.removeEventListener('keydown', splashKeyHandler);
  // Wait for the fade-out transition before letting the tutorial appear,
  // so the two overlays never visually overlap.
  setTimeout(() => {
    splash.remove();
    showTutorialIfNeeded();
  }, 620);
}
function splashKeyHandler(e) {
  if (e.key === 'Enter' || e.key === ' ' || e.key === 'Escape') dismissSplash();
}

(function initSplash() {
  const splash = document.getElementById('splashScreen');
  if (!splash) return;
  splash.addEventListener('click', dismissSplash);
  window.addEventListener('keydown', splashKeyHandler);
  setTimeout(dismissSplash, SPLASH_AUTO_DISMISS_MS);
})();

/* ============================================================
   INITIALIZE
   ============================================================ */
initStarfield();
renderThemeBar();
updateAetherDisplay();

// Start game immediately, init SDK in background (don't block)
initGame();
crazySdk.init().then(async () => {
  crazySdk.game.loadingStop();

  // Re-read lifetime progress now that the real SDK's data module (cloud save) is live,
  // rather than relying only on the localStorage fallback used at page-start. Reconciled
  // rather than blindly overwritten in either direction, so progress made on another
  // device (in the cloud save) and progress made in this tab before init finished are
  // both preserved.
  const sdkProgress = loadProgress();
  PROGRESS = mergeProgress(PROGRESS, sdkProgress);
  saveProgress();
  renderThemeBar();
  updateAetherDisplay();

  showTutorialIfNeeded();

  // If the player is signed in to their CrazyGames account, greet them by name.
  // Purely cosmetic — no ads, no gating, safe for Basic Launch.
  if (crazySdk.user.isUserAccountAvailable) {
    try {
      const user = await crazySdk.user.getUser();
      if (user && user.username) {
        queueAchievementToast({ icon: '✦', title: 'Welcome back', name: user.username });
      }
    } catch(e) {}
  }
});
